//! Rustergraphia CLI Tool
//! ======================
//!
//! Purpose:
//! - Command-line interface for the Cistergraphia cipher system (Rust port)
//! - Converts messages to SVG and optionally PNG
//! - Decodes an SVG generated by either implementation back into its message
//! - --secret switches to secret mode (passphrase, AES-256-GCM)
//! - --layout picks the reading path; decoding detects the keyless five. A
//!   grille plate needs its key (--grille): writing without one draws a new
//!   grille and prints its key, and --stencil writes the grille to print and
//!   cut. --decoy adds a second message for a second reader
//! - --weathered writes a game plate that has lost some strokes; decoding a
//!   weathered plate restores what the pairs decide and prints the edition
//!   in the Leiden conventions: [r] restored, [b/l] for the reader to settle
//! - --broken writes a game plate in two to four fragments; decoding a
//!   broken plate rejoins it by its sums
//!
//! Design Decisions:
//! - SVG rendering is shared with the web app (the rustergraphia crate)
//! - External tools are invoked without a shell, so paths are never
//!   interpreted
//! - The passphrase is never a command-line argument (shell history, ps):
//!   it is prompted without echo, or read from CISTERGRAPHIA_PASSPHRASE for
//!   scripts

use std::io::{IsTerminal, Write};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use clap::Parser;

use rustergraphia::grille::{Grille, Part};
use rustergraphia::layout::Layout;
use rustergraphia::{cipher, fragments, lacunae, pathless, secret, tablet, tally, two_readers};
use rustergraphia::{Error, RubyRandom};

#[derive(Parser, Debug)]
#[command(
    name = "rustergraphia",
    about = "Your secrets, in a monk's handwriting",
    disable_help_subcommand = true
)]
struct Options {
    /// The message to convert
    #[arg(short, long)]
    message: Option<String>,

    /// The output file path for the SVG
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// The output file path for the PNG
    #[arg(short, long)]
    png: Option<PathBuf>,

    /// Decode a Cistergraphia SVG and print its message
    #[arg(short, long, value_name = "FILE")]
    decode: Option<PathBuf>,

    /// Reading path: phaistos (the snail, default), rongorongo, leap,
    /// furrows, unwinding or grille
    #[arg(short, long, value_parser = ["phaistos", "rongorongo", "leap", "furrows", "unwinding", "grille"])]
    layout: Option<String>,

    /// The grille's key (K7Q2M-ZXB4P): writes or reads under it
    #[arg(short, long, value_name = "KEY")]
    grille: Option<String>,

    /// Also write the grille as a stencil to print and cut
    #[arg(long, value_name = "FILE")]
    stencil: Option<PathBuf>,

    /// A second message, for a novice's grille (implies a grille)
    #[arg(long, value_name = "MESSAGE")]
    decoy: Option<String>,

    /// Game mode: a worn plate, some strokes lost to restore
    #[arg(short, long)]
    weathered: bool,

    /// Game mode: the plate in fragments, to rejoin (the snail only)
    #[arg(short, long)]
    broken: bool,

    /// Game mode: the reader finds the way, the plate says nothing
    #[arg(long)]
    pathless: bool,

    /// Game mode: a tablet of the plate's own; the reader builds it in the
    /// notebook
    #[arg(long = "own-tablet")]
    own_tablet: bool,

    /// Game mode: row and column sums (with -w, whole signs are lost too)
    #[arg(short, long)]
    tally: bool,

    /// Secret mode: encrypt/decrypt with a passphrase (prompted, or taken
    /// from CISTERGRAPHIA_PASSPHRASE)
    #[arg(short, long)]
    secret: bool,
}

fn main() -> ExitCode {
    match run(Options::parse()) {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("{message}");
            ExitCode::FAILURE
        }
    }
}

fn run(options: Options) -> Result<(), String> {
    if options.decode.is_some() {
        return decode(&options);
    }
    inscribe(&options)
}

/// The layout to write or read with: a grille when a key is given or a
/// grille asked for.
fn layout_for(options: &Options, writing: bool) -> Result<Option<Layout>, String> {
    if let Some(key) = &options.grille {
        let grille = Grille::new(key, Part::Whole).map_err(|e| e.to_string())?;
        return Ok(Some(Layout::Grille(grille)));
    }
    if writing && (options.layout.as_deref() == Some("grille") || options.decoy.is_some()) {
        return Ok(Some(Layout::Grille(Grille::generate())));
    }
    if !writing {
        return Ok(None);
    }
    Ok(Some(match options.layout.as_deref() {
        Some("rongorongo") => Layout::Rongorongo,
        Some("leap") => Layout::Leap,
        Some("furrows") => Layout::Furrows,
        Some("unwinding") => Layout::Unwinding,
        _ => Layout::Phaistos,
    }))
}

fn decode(options: &Options) -> Result<(), String> {
    let path = options.decode.as_ref().expect("checked by caller");
    let svg = std::fs::read_to_string(path).map_err(|e| format!("{} - {}", e, path.display()))?;
    let passphrase = if options.secret {
        Some(ask_passphrase(false)?)
    } else {
        None
    };
    let grille = layout_for(options, false)?;
    let result = match &grille {
        None => cipher::decode(&svg, passphrase.as_deref(), None).map(|message| {
            println!("{message}");
        }),
        Some(Layout::Grille(key)) => {
            two_readers::read(&svg, key, passphrase.as_deref()).map(|reading| {
                println!("{}", reading.message);
                if let Some(decoy) = reading.decoy {
                    println!("The novice's grille reads: {decoy}");
                }
            })
        }
        Some(_) => unreachable!("layout_for returns a grille or nothing when reading"),
    };
    result.map_err(|error| match error {
        Error::GrilleKeyNeeded(message) => format!("{message}. Add --grille KEY."),
        error if error.is_decode() => {
            let hint = if options.secret || options.grille.is_some() {
                ""
            } else {
                ". If this image was made in secret mode, add --secret."
            };
            format!("{error}{hint}")
        }
        error => error.to_string(),
    })
}

fn inscribe(options: &Options) -> Result<(), String> {
    let message = match &options.message {
        Some(message) => message.clone(),
        None => {
            print!("What is your message? ");
            std::io::stdout().flush().ok();
            let mut line = String::new();
            std::io::stdin().read_line(&mut line).ok();
            line.trim_end_matches(['\n', '\r']).to_string()
        }
    };

    let layout = layout_for(options, true)?.expect("writing always has a layout");
    let under_grille = matches!(layout, Layout::Grille(_));
    if options.stencil.is_some() && !under_grille {
        return Err("--stencil needs a grille: add --layout grille or --grille KEY".to_string());
    }
    refuse(options, under_grille)?;
    let own_tablet = options.own_tablet.then(tablet::generate);
    let passphrase = if options.secret {
        Some(ask_passphrase(true)?)
    } else {
        None
    };

    let mut random = RubyRandom::new_os();
    let (sequence, svg, written_layout);
    if options.broken {
        let (seq, drawn, pieces, damage) =
            fragments::inscribe(&message, &layout, options.weathered, &mut random)
                .map_err(|e| e.to_string())?;
        let worn = if damage.is_empty() {
            String::new()
        } else {
            format!(", {} lacunae", damage.len())
        };
        println!(
            "Broken: {} fragments{worn}. Rejoin them on the board: every pair must balance (-d rejoins them)",
            pieces.len()
        );
        (sequence, svg, written_layout) = (seq, drawn, layout);
    } else if options.weathered {
        let (seq, drawn, damage) = lacunae::inscribe(
            &message,
            &layout,
            passphrase.as_deref(),
            options.tally,
            options.pathless,
            &mut random,
        )
        .map_err(|e| e.to_string())?;
        let lacunae_count = if damage.len() == 1 {
            "1 lacuna".to_string()
        } else {
            format!("{} lacunae", damage.len())
        };
        println!("Weathered: {lacunae_count}. Restore them by balancing the pairs (-d shows the edition)");
        if options.pathless {
            println!("Pathless: the plate says nothing of where it begins; the bench finds the way");
        }
        (sequence, svg, written_layout) = (seq, drawn, layout);
    } else if let Some(decoy) = &options.decoy {
        let given = options.grille.is_some().then(|| match &layout {
            Layout::Grille(grille) => grille.clone(),
            _ => unreachable!("a decoy implies a grille"),
        });
        let (seq, drawn, abbot) =
            two_readers::inscribe(&message, decoy, passphrase.as_deref(), given.as_ref())
                .map_err(|e| e.to_string())?;
        (sequence, svg, written_layout) = (seq, drawn, Layout::Grille(abbot));
    } else {
        let (seq, drawn) = cipher::inscribe(
            &message,
            passphrase.as_deref(),
            &layout,
            options.tally,
            options.pathless,
            own_tablet.as_deref(),
            &mut random,
        )
        .map_err(|e| e.to_string())?;
        if options.pathless {
            println!("Pathless: the plate says nothing of where it begins; -d finds the way");
        }
        if let Some(seed) = &own_tablet {
            println!("{}", tablet_lines(seed)?);
        }
        (sequence, svg, written_layout) = (seq, drawn, layout);
    }

    if let Layout::Grille(grille) = &written_layout {
        let grilles = if options.decoy.is_some() {
            println!("Abbot's key: {grille} (reads both messages; keep it)");
            println!("Novice's key: {} (reads the decoy only)", grille.novice());
            vec![grille.as_part(Part::Abbot), grille.novice()]
        } else {
            println!("Grille key: {grille} (the plate cannot be read without it)");
            vec![grille.clone()]
        };
        if let Some(path) = &options.stencil {
            write_stencils(path, sequence.len().isqrt(), &grilles)?;
        }
    }

    let svg_path = options
        .output
        .clone()
        .unwrap_or_else(|| default_dir().join("inline.svg"));
    let png_path = options
        .png
        .clone()
        .unwrap_or_else(|| default_dir().join("output.png"));
    for path in [&svg_path, &png_path] {
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
        }
    }
    std::fs::write(&svg_path, &svg).map_err(|e| e.to_string())?;
    display_svg(&svg_path);
    convert_to_png(&svg_path, &png_path);
    Ok(())
}

/// The combinations the library refuses, in its words, before any work.
fn refuse(options: &Options, under_grille: bool) -> Result<(), String> {
    let refusals: [(bool, &str); 6] = [
        (options.weathered && options.secret, lacunae::NOT_SEALED),
        (options.tally && options.secret, tally::NOT_SEALED),
        (
            options.weathered && options.decoy.is_some(),
            lacunae::NOT_TWO_READERS,
        ),
        (options.broken && options.secret, fragments::NOT_SEALED),
        (options.broken && options.tally, fragments::NOT_TALLIED),
        (options.pathless && options.broken, pathless::NOT_BROKEN),
    ];
    for (refused, message) in refusals {
        if refused {
            return Err(message.to_string());
        }
    }
    if options.own_tablet {
        if options.secret {
            return Err(tablet::NOT_SEALED.to_string());
        }
        if options.weathered || options.broken {
            return Err(tablet::NOT_DAMAGED.to_string());
        }
        if under_grille || options.decoy.is_some() {
            return Err(tablet::NOT_UNDER_A_GRILLE.to_string());
        }
    }
    Ok(())
}

/// A plate's own tablet, as the scribe should see it: the seed, then the
/// twenty-seven rows in three columns.
fn tablet_lines(seed: &str) -> Result<String, String> {
    let rows: Vec<String> = tablet::rows(seed)
        .map_err(|e| e.to_string())?
        .into_iter()
        .map(|(c, value)| {
            format!(
                "{} {:04}",
                if c == ' ' { '\u{2423}' } else { c },
                value
            )
        })
        .collect();
    let columns: Vec<&[String]> = rows.chunks(9).collect();
    let mut lines = vec![format!(
        "Its own tablet (seed {}): the reader builds it in the notebook; -d reads it",
        tablet::show(seed).map_err(|e| e.to_string())?
    )];
    for i in 0..columns[0].len() {
        let row: Vec<&str> = columns
            .iter()
            .filter_map(|column| column.get(i).map(String::as_str))
            .collect();
        lines.push(row.join("    "));
    }
    Ok(lines.join("\n"))
}

/// The stencils to print and cut: the grille's, or the abbot's and the
/// novice's.
fn write_stencils(path: &Path, size: usize, grilles: &[Grille]) -> Result<(), String> {
    if let Some(dir) = path.parent() {
        if !dir.as_os_str().is_empty() {
            std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
        }
    }
    for (i, grille) in grilles.iter().enumerate() {
        let file = if i == 0 {
            path.to_path_buf()
        } else {
            let text = path.to_string_lossy();
            PathBuf::from(match text.strip_suffix(".svg") {
                Some(stem) => format!("{stem}-novice.svg"),
                None => format!("{text}-novice.svg"),
            })
        };
        let stencil =
            rustergraphia::svg::stencil(size, grille).map_err(|e| e.to_string())?;
        std::fs::write(&file, stencil).map_err(|e| e.to_string())?;
    }
    Ok(())
}

fn ask_passphrase(confirm: bool) -> Result<String, String> {
    if let Ok(from_env) = std::env::var("CISTERGRAPHIA_PASSPHRASE") {
        if !from_env.is_empty() {
            return Ok(from_env);
        }
    }
    if !std::io::stdin().is_terminal() {
        return Err(
            "Secret mode needs a terminal to prompt for the passphrase, or CISTERGRAPHIA_PASSPHRASE"
                .to_string(),
        );
    }
    let passphrase =
        rpassword::prompt_password("Passphrase: ").map_err(|e| e.to_string())?;
    if confirm {
        if let Some(problem) = secret::passphrase_problem(&passphrase) {
            return Err(problem); // before asking for it twice
        }
        let repeat =
            rpassword::prompt_password("Repeat passphrase: ").map_err(|e| e.to_string())?;
        if repeat != passphrase {
            return Err("Passphrases do not match".to_string());
        }
    }
    Ok(passphrase)
}

fn default_dir() -> PathBuf {
    PathBuf::from("tmp")
}

fn command_exists(name: &str) -> bool {
    std::env::var_os("PATH")
        .map(|paths| {
            std::env::split_paths(&paths).any(|dir| {
                let path = dir.join(name);
                path.is_file()
                    && std::fs::metadata(&path)
                        .map(|m| {
                            use std::os::unix::fs::PermissionsExt;
                            m.permissions().mode() & 0o111 != 0
                        })
                        .unwrap_or(false)
            })
        })
        .unwrap_or(false)
}

fn display_svg(path: &Path) {
    if command_exists("chafa") {
        std::process::Command::new("chafa").arg(path).status().ok();
    }
}

fn convert_to_png(input: &Path, output: &Path) {
    let converter: Option<Vec<&std::ffi::OsStr>> = if command_exists("rsvg-convert") {
        Some(vec![
            "rsvg-convert".as_ref(),
            "-o".as_ref(),
            output.as_os_str(),
            input.as_os_str(),
        ])
    } else if command_exists("magick") {
        Some(vec!["magick".as_ref(), input.as_os_str(), output.as_os_str()])
    } else if command_exists("convert") {
        Some(vec!["convert".as_ref(), input.as_os_str(), output.as_os_str()])
    } else {
        None
    };
    let Some(parts) = converter else {
        eprintln!("Skipping PNG: install librsvg (rsvg-convert) or ImageMagick");
        return;
    };
    let status = std::process::Command::new(parts[0]).args(&parts[1..]).status();
    match status {
        Ok(status) if status.success() => {}
        Ok(status) => eprintln!(
            "PNG conversion failed: {} exited with {}",
            parts[0].to_string_lossy(),
            status.code().map_or_else(|| "?".to_string(), |c| c.to_string())
        ),
        Err(error) => eprintln!(
            "PNG conversion failed: {} ({error})",
            parts[0].to_string_lossy()
        ),
    }
}
